var detectMeetingService=function(n){let t;try{t=new URL(n).hostname}catch(i){return"invalid URL"}return t.includes("zoom.us")?"Zoom":t.includes("teams.microsoft.com")?"Microsoft Teams":t.includes("meet.google.com")?"Google Meet":t.includes("webex.com")?"Cisco Webex":t.includes("gotomeeting.com")?"GoToMeeting":t.includes("whereby.com")?"Whereby":t.includes("bluejeans.com")?"BlueJeans":JSR.browse};